// Phase-2 acceptance (docs/plan/05-migration.md): the tables generated by
// `bun run render` match the v0-final README cell for cell — the regression
// test for the whole data model. Run: `bun run scripts/acceptance-phase2.ts`
//
// Target tables are parsed from `git show v0-final:README.md`; generated
// tables are parsed from the current README's <!-- gen:… --> sections.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { type MdTable, parseTables } from "../bench/src/render/markdown.ts";

const repoRoot = join(import.meta.dir, "..");

const v0 = await Bun.$`git show v0-final:README.md`.text();
const current = readFileSync(join(repoRoot, "README.md"), "utf8");

const targetTables = parseTables(v0);
const generatedTables = parseTables(current);

// compare by matching headings; report every missing/extra/differing table
const byHeading = (ts: MdTable[]) => new Map(ts.map((t) => [t.heading, t]));
const target = byHeading(targetTables);
const generated = byHeading(generatedTables);

let failures = 0;
const compare = (t: MdTable, g: MdTable | undefined, label: string) => {
  if (!g) {
    console.error(`FAIL [${label}] no generated table under heading "${t.heading}"`);
    failures++;
    return;
  }
  if (t.header.join("|") !== g.header.join("|")) {
    console.error(`FAIL [${label}] header differs under "${t.heading}"`);
    console.error(`  target:   ${t.header.join("|")}`);
    console.error(`  generated:${g.header.join("|")}`);
    failures++;
    return;
  }
  if (t.rows.length !== g.rows.length) {
    console.error(
      `FAIL [${label}] "${t.heading}": ${t.rows.length} target rows vs ${g.rows.length} generated`,
    );
    failures++;
    return;
  }
  for (let r = 0; r < t.rows.length; r++) {
    const tr = t.rows[r] ?? [];
    const gr = g.rows[r] ?? [];
    for (let c = 0; c < Math.max(tr.length, gr.length); c++) {
      if ((tr[c] ?? "") !== (gr[c] ?? "")) {
        console.error(
          `FAIL [${label}] "${t.heading}" row ${r + 1} col ${c + 1}: target "${tr[c] ?? ""}" != generated "${gr[c] ?? ""}"`,
        );
        failures++;
        return; // first mismatch per table is enough to act on
      }
    }
  }
  console.log(`OK   [${label}] "${t.heading}" (${t.rows.length} rows)`);
};

// every numeric benchmark table in the v0 README must be reproduced
const benchmarkHeadings = targetTables
  .map((t) => t.heading)
  .filter((h) =>
    ["Mixed-pool spectrum benchmark", "Multilingual", "NER", "rerank", "trial", "cost"].some((k) =>
      h.toLowerCase().includes(k.toLowerCase()),
    ),
  );

if (benchmarkHeadings.length === 0) {
  console.error("FAIL found no benchmark tables in the v0-final README (parser?)");
  process.exit(1);
}

for (const heading of benchmarkHeadings) {
  const t = target.get(heading);
  if (!t) continue;
  compare(t, generated.get(heading), "v0");
}

console.log(`phase-2 acceptance: ${benchmarkHeadings.length} target tables, ${failures} failures`);
if (failures > 0) process.exit(1);
